<script setup>
import {computed,ref} from 'vue';
import {bandEvents,calendarChecked} from '../../data/calendar.js';
import {eventsInYear,makeIcal} from '../../room/calendar.js';
import {loadLocal,saveLocal} from '../../room/storage.js';
import {countEvent} from '../../services/analytics.js';
const now=new Date(),year=ref(now.getFullYear()),month=ref(now.getMonth()+1),kind=ref('all'),onlyMine=ref(false),message=ref('');
const following=ref(loadLocal('hitori-room:calendar-follow:v1',[],v=>{if(!Array.isArray(v))throw new Error();return v.filter(id=>bandEvents.some(e=>e.id===id));}));
const annual=computed(()=>!Number.isInteger(year.value)||year.value<2000||year.value>2100?[]:eventsInYear(bandEvents,year.value).filter(e=>(kind.value==='all'||e.kind===kind.value)&&(!onlyMine.value||following.value.includes(e.id))));
const monthly=computed(()=>annual.value.filter(e=>Number(e.date.slice(5,7))===month.value));
const cells=computed(()=>{const first=new Date(Date.UTC(year.value,month.value-1,1)).getUTCDay(),length=new Date(Date.UTC(year.value,month.value,0)).getUTCDate();return [...Array(first).fill(null),...Array.from({length},(_,i)=>({day:i+1,date:`${year.value}-${String(month.value).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`}))];});
const upcoming=computed(()=>[...eventsInYear(bandEvents,now.getFullYear()),...eventsInYear(bandEvents,now.getFullYear()+1)].filter(e=>e.date>=now.toISOString().slice(0,10)).slice(0,7));
function scrollEvent(id){document.getElementById('event-'+id)?.scrollIntoView({block:'center'});}
function navigate(delta){const d=new Date(year.value,month.value-1+delta,1);if(d.getFullYear()<2000||d.getFullYear()>2100)return;year.value=d.getFullYear();month.value=d.getMonth()+1;}
function follow(e){following.value=following.value.includes(e.id)?following.value.filter(id=>id!==e.id):[...following.value,e.id];message.value=saveLocal('hitori-room:calendar-follow:v1',following.value)?'关注已保存在本机。':'本机无法保存关注，可以导出日历。';}
function exportCalendar(){try{const events=onlyMine.value?bandEvents.filter(e=>following.value.includes(e.id)):bandEvents.filter(e=>kind.value==='all'||e.kind===kind.value);const text=makeIcal(events,year.value),url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`hitori-calendar-${year.value}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);countEvent('export','calendar');message.value='已导出日历文件，可导入手机或桌面日历。生日和纪念日按年重复。';}catch(e){message.value=e.message;}}
</script>
<template><section class="room-panel" aria-labelledby="calendar-title"><p class="play-eyebrow">把喜欢的日子，记进日历</p><h2 id="calendar-title">下一次相遇，在什么时候？</h2><p class="room-intro">公开演出、发售日与角色纪念日。信息核对于{{calendarChecked}}；有变动时以每条日程的官方来源为准，未公布的截止时间不作推测。</p><div class="calendar-controls"><button aria-label="上个月" type="button" @click="navigate(-1)">←</button><strong>{{year}}年{{month}}月</strong><button aria-label="下个月" type="button" @click="navigate(1)">→</button><button type="button" @click="year=now.getFullYear();month=now.getMonth()+1">回到本月</button></div><div class="room-fields"><label class="room-field">年份<input v-model.number="year" type="number" min="2000" max="2100"></label><label class="room-field">类型<select v-model="kind"><option value="all">全部类型</option><option v-for="k in ['生日','纪念','演出','发售']" :key="k">{{k}}</option></select></label></div><label class="room-check"><input v-model="onlyMine" type="checkbox">只看我关注的日程</label><div v-if="year>=2000&&year<=2100" class="calendar-month"><span v-for="d in ['日','一','二','三','四','五','六']" :key="d" class="calendar-weekday">{{d}}</span><div v-for="(cell,i) in cells" :key="i" class="calendar-day" :class="{'has-event':cell&&monthly.some(e=>e.date===cell.date)}"><template v-if="cell"><strong>{{cell.day}}</strong><button v-for="e in monthly.filter(e=>e.date===cell.date)" :key="e.id" type="button" :aria-label="e.title" :title="e.title" @click="scrollEvent(e.id)"><span class="calendar-label">{{e.title}}</span><span class="calendar-kind" aria-hidden="true">{{e.kind}}</span></button></template></div></div><div class="room-actions"><button id="calendar-export" type="button" @click="exportCalendar">导出{{onlyMine?'关注':'本年'}}日历 ICS ↓</button></div><p class="room-status" role="status">{{message}}</p><h3>本月日程</h3><p v-if="!monthly.length">这个月暂时没有收录相应日程，可以切换类型或看看接下来的日子。</p><article v-for="e in monthly" :id="'event-'+e.id" :key="e.id" class="calendar-event"><small>{{e.date}} · {{e.kind}} {{e.date<now.toISOString().slice(0,10)?'· 已过去':''}}</small><h3>{{e.title}}</h3><p>{{e.description}}</p><div class="resource-actions"><button type="button" :aria-pressed="following.includes(e.id)" @click="follow(e)">{{following.includes(e.id)?'已关注 ✓':'关注这一天 ＋'}}</button><a :href="e.source" target="_blank" rel="noopener noreferrer">官方来源 ↗</a></div></article><h3>接下来的日子</h3><ul><li v-for="e in upcoming" :key="e.id+e.date"><button type="button" @click="year=Number(e.date.slice(0,4));month=Number(e.date.slice(5,7));onlyMine=false;kind='all'">{{e.date}} · {{e.title}}</button></li></ul></section></template>
